export const DEFAULT_PLAYER_ROLE_ANALYTICS = KSCERATO_ROLE_ANALYTICS;

const PLAYERS_MAP: Record<string, PlayerRoleAnalyticsDTO> = {
  kscerato: KSCERATO_ROLE_ANALYTICS,
  '76561198000000001': KSCERATO_ROLE_ANALYTICS,
  niko: NIKO_ROLE_ANALYTICS,
  '76561198041683378': NIKO_ROLE_ANALYTICS,
  monesy: MONESY_ROLE_ANALYTICS,
  '76561198308801880': MONESY_ROLE_ANALYTICS,
};

export function getPlayerRoleAnalytics(identifier?: string | null): PlayerRoleAnalyticsDTO {
  if (!identifier) return DEFAULT_PLAYER_ROLE_ANALYTICS;
  const key = identifier.toLowerCase().trim();
  return PLAYERS_MAP[key] ?? DEFAULT_PLAYER_ROLE_ANALYTICS;
}

